    and a.segm_type in

        #{segmType}

mapper.select:
select *
from ADDR_SEGM
where coalesce(delete_state, '0') = '0'
  and parent_segm_id = #{parentSegmId}
  and segm_name = #{segmName}

select a.segm_id as segmId, a.parent_segm_id as parentSegmId, a.segm_name as segmName, a.stand_name as standName, a.segm_no as segmNo, a.segm_type as segmType, a.region_id as regionId, a.status as status from ADDR_SEGM a
coalesce(a.delete_state, '0') = '0'
and ( a.segm_name like #{keywordLike} or a.stand_name like #{keywordLike} )
and a.segm_type in
#{segmType}
and a.status = #{status}
order by case
when a.segm_type = #{segmType} then ${index}
else 999999 end, a.segm_id asc
order by a.segm_id asc
